WITH filtered AS (SELECT id, order_id, carrier, shipped_date, delivered_date, cost, status, CASE WHEN carrier = 'DHL' THEN 1 ELSE 0 END AS is_dhl FROM shipments WHERE carrier IS DISTINCT FROM 'Flash') SELECT *, COUNT(is_dhl) OVER w_ordered AS order_id_count_is_dhl, SUM(is_dhl) OVER w_hist AS cumulative_is_dhl, SUM(is_dhl) OVER w_part AS running_is_dhl, STDDEV_SAMP(is_dhl) OVER (PARTITION BY carrier) AS carrier_stddev_samp_is_dhl, NTILE(4) OVER w_recent AS cost_bucket FROM filtered WHERE order_id IN (3, 11, 14) WINDOW w_ordered AS (PARTITION BY order_id), w_hist AS (PARTITION BY carrier, order_id ORDER BY shipped_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW), w_part AS (PARTITION BY order_id ORDER BY cost, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW), w_recent AS (PARTITION BY carrier, order_id ORDER BY cost, id)
